CREATE OR REPLACE FUNCTION public.can_manage_farm(p_farmer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) OR EXISTS(SELECT 1 FROM public.comm_org_members manager JOIN public.comm_org_members farmer ON farmer.org_id=manager.org_id WHERE manager.user_id=auth.uid() AND manager.role='manager' AND farmer.user_id=p_farmer) $$;
CREATE OR REPLACE FUNCTION public.workspace_management() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) OR EXISTS(SELECT 1 FROM public.comm_org_members WHERE user_id=auth.uid() AND role='manager') $$;
GRANT EXECUTE ON FUNCTION public.can_manage_farm(uuid), public.workspace_management() TO authenticated;
DROP POLICY "farmer or staff read harvests" ON public.harvests;
CREATE POLICY harvest_financial_management_read ON public.harvests FOR SELECT TO authenticated USING(public.can_manage_farm(farmer_id));
DROP POLICY "farmer creates own pending harvest" ON public.harvests;
CREATE POLICY harvest_management_insert ON public.harvests FOR INSERT TO authenticated WITH CHECK(public.workspace_management() AND farmer_id=auth.uid() AND status='pending' AND reviewed_by IS NULL);
DROP POLICY "hq reviews harvests" ON public.harvests;
CREATE POLICY harvest_management_review ON public.harvests FOR UPDATE TO authenticated USING(public.can_manage_farm(farmer_id)) WITH CHECK(public.can_manage_farm(farmer_id));
CREATE OR REPLACE FUNCTION public.operational_harvests() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(jsonb_agg(to_jsonb(h) ORDER BY h.harvest_date DESC,h.id),'[]'::jsonb) FROM (SELECT id,farmer_id,photo_path,vegetable,quantity,unit,destination,status,created_at,field_name,grade,harvest_date,reviewed_at FROM public.harvests WHERE farmer_id=auth.uid() OR public.can_manage_farm(farmer_id)) h WHERE auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.operational_harvests() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.operational_harvests() TO authenticated;
CREATE OR REPLACE FUNCTION public.submit_operational_harvest(p_record jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_record ?| ARRAY['expected_revenue','cost','currency','status','reviewed_by','farmer_id'] THEN RAISE EXCEPTION 'Restricted fields'; END IF; IF (p_record->>'photo_path') IS NOT NULL AND (p_record->>'photo_path') NOT LIKE auth.uid()::text || '/%' THEN RAISE EXCEPTION 'Invalid photo owner'; END IF; INSERT INTO public.harvests(farmer_id,vegetable,quantity,unit,destination,grade,field_name,harvest_date,photo_path,notes,ai_summary,expected_revenue,cost,currency) VALUES(auth.uid(),p_record->>'vegetable',(p_record->>'quantity')::numeric,'kg',p_record->>'destination',COALESCE(p_record->>'grade','A'),p_record->>'field_name',(p_record->>'harvest_date')::date,p_record->>'photo_path',p_record->>'notes',p_record->>'ai_summary',0,0,COALESCE((SELECT currency FROM public.user_settings WHERE user_id=auth.uid()),'CNY')) RETURNING id INTO new_id; RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.submit_operational_harvest(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_operational_harvest(jsonb) TO authenticated;
DROP POLICY reports_owner_read ON public.farm_reports;
CREATE POLICY reports_management_read ON public.farm_reports FOR SELECT TO authenticated USING(public.can_manage_farm(user_id));
DROP POLICY "own notifications read" ON public.notifications;
CREATE POLICY notifications_permitted_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid() AND (event_type='communication' OR public.workspace_management()));
DROP POLICY goals_owner ON public.farmer_goals;
CREATE POLICY goals_permitted_owner ON public.farmer_goals FOR ALL TO authenticated USING(user_id=auth.uid() AND (metric='custom' OR public.workspace_management())) WITH CHECK(user_id=auth.uid() AND (metric='custom' OR public.workspace_management()));
ALTER TABLE public.guide_messages ADD COLUMN management_only boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.classify_guide_message() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.management_only := public.workspace_management(); RETURN NEW; END $$;
CREATE TRIGGER classify_guide_message BEFORE INSERT ON public.guide_messages FOR EACH ROW EXECUTE FUNCTION public.classify_guide_message();
DROP POLICY own_guide_messages ON public.guide_messages;
CREATE POLICY guide_messages_permitted_read ON public.guide_messages FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.guide_threads t WHERE t.id=thread_id AND t.user_id=auth.uid()) AND (message->>'role'='user' OR NOT management_only OR public.workspace_management()));
CREATE POLICY guide_messages_owner_insert ON public.guide_messages FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.guide_threads t WHERE t.id=thread_id AND t.user_id=auth.uid()));
CREATE POLICY guide_messages_owner_delete ON public.guide_messages FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.notify_harvest() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE payload jsonb; BEGIN payload:=jsonb_build_object('vegetable',NEW.vegetable,'quantity',NEW.quantity,'destination',NEW.destination,'revenue',NEW.expected_revenue,'cost',NEW.cost,'currency',NEW.currency,'status',NEW.status); IF TG_OP='INSERT' OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status<>'pending') THEN INSERT INTO public.notifications(user_id,title,body,harvest_id,event_type,details) SELECT DISTINCT user_id,'Harvest update','',NEW.id,CASE WHEN TG_OP='INSERT' THEN 'harvest_submitted' ELSE 'harvest_reviewed' END,payload FROM public.user_roles WHERE role='hq'; END IF; RETURN NEW; END $$;